    },
    {
      "id": "s9",
      "title": "处理登录成功",
      "detail": "写 SUCCESS 事件、发送成功 MQ 消息并生成 token-用户ID。",
      "source_ids": [
        "sr1:e813e1eb",
        "sr1:e2fc2b52"
      ]
    },
    {
      "id": "s10",
      "title": "返回认证响应",
      "detail": "Controller 将 token 和 fromSso 封装为 AuthResponse。",
      "source_ids": [
        "sr1:f000bda0",
        "sr1:4073e8e6"
      ]
    }
  ],
